/* ===== BLUEGPT RELAXING RETRO THEME (ADAPTIVE + FIXED BLUE) ===== */

/* Full-page background */
html, body {
    height: 100%;
    width: 100%;
    margin: 0;
    padding: 0;
    background: url('https://getwallpapers.com/wallpaper/full/d/2/7/1498104-cool-mind-relaxing-wallpapers-1920x1240-high-resolution.jpg') no-repeat center center fixed;
    background-size: cover;
    font-family: 'Courier New', monospace !important;
    color: #e0e0ff !important;
    line-height: 1.5 !important;
}

/* General text for adaptivity */
body, p, span, div, li, td, th, a, h1, h2, h3, h4, h5, h6 {
    color: #e0e0ff !important;
    text-shadow: 0 0 2px rgba(0,0,0,0.6);
}

/* Links */
a {
    color: #66ccff !important;
    text-decoration: none !important;
}

a:hover {
    color: #99ddff !important;
    text-decoration: underline !important;
}

/* Headers */
h1,h2,h3,h4,h5,h6 {
    color: #99ccff !important;
    text-shadow: 1px 1px 3px #000000aa;
}

/* Inputs & Buttons (forms & Google search) */
input, textarea, select, button {
    background-color: rgba(30,30,50,0.85) !important;
    color: #e0e0ff !important;
    border: 2px solid #4da6ff !important;
    border-radius: 10px !important;
    padding: 6px 10px !important;
    font-family: 'Courier New', monospace !important;
}

/* Input placeholders */
input::placeholder, textarea::placeholder {
    color: #a0a0ff !important;
}

/* Buttons hover */
button:hover, input[type="submit"]:hover {
    background-color: #3399ff !important;
    color: #fff !important;
}

/* Google search styling */
input[name="q"] {
    background-color: rgba(30,30,50,0.9) !important;
    color: #e0e0ff !important;
    border: 2px solid #4da6ff !important;
    border-radius: 12px !important;
    padding: 8px 12px !important;
}

input[name="btnK"], input[name="btnI"] {
    background-color: #4da6ff !important;
    color: #fff !important;
    border-radius: 12px !important;
    padding: 6px 14px !important;
    border: none !important;
}

input[name="btnK"]:hover, input[name="btnI"]:hover {
    background-color: #3399ff !important;
}

/* Retro elements */
code, pre {
    background-color: rgba(0,0,0,0.7) !important;
    color: #00ffcc !important;
    padding: 4px 6px !important;
    border-radius: 4px !important;
    font-family: 'Courier New', monospace !important;
}

/* Scrollbar styling */
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-thumb {
    background-color: #4da6ff !important;
    border-radius: 6px;
}

::-webkit-scrollbar-track {
    background-color: rgba(30,30,50,0.5) !important;
}

/* Tables adaptive */
table, th, td {
    border: 1px solid #4da6ff !important;
    color: #e0e0ff !important;
}

/* Adaptive background overlay for readability */
* {
    background: rgba(0,0,0,0.0) !important;
}

/* Fixing blue placements for buttons, highlights, and links */
::selection {
    background-color: #3399ff !important;
    color: #ffffff !important;
}

/* Ensure images and videos scale nicely */
img, video, iframe {
    max-width: 100% !important;
    height: auto !important;
}

/* Responsive text sizing */
body {
    font-size: 1em !important;
}

h1 { font-size: 2em !important; }
h2 { font-size: 1.8em !important; }
h3 { font-size: 1.6em !important; }
h4 { font-size: 1.4em !important; }
h5 { font-size: 1.2em !important; }
h6 { font-size: 1em !important; }
